BEGIN;
UPDATE finance_offices SET name='Main Finance Office',active=TRUE,updated_at=NOW() WHERE code='MAIN_CFO' OR LOWER(name) IN('finance main','cfo office','finance main and cfo office');
INSERT INTO finance_offices(code,name,active) VALUES('MAIN_CFO','Main Finance Office',TRUE) ON CONFLICT(code) DO UPDATE SET name='Main Finance Office',active=TRUE,updated_at=NOW();
INSERT INTO finance_locations(code,name,location_type,active,external_auditor_use,finance_host_required,visitor_approval_required)
VALUES('FIN_BOARDROOM','Finance Boardroom','meeting_room',TRUE,TRUE,TRUE,TRUE)
ON CONFLICT(code) DO UPDATE SET name='Finance Boardroom',location_type='meeting_room',active=TRUE,external_auditor_use=TRUE,finance_host_required=TRUE,visitor_approval_required=TRUE,updated_at=NOW();
CREATE TABLE IF NOT EXISTS finance_employee_governance_events(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),action VARCHAR(30) NOT NULL,reason TEXT NOT NULL,snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,actor_user_id BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS finance_graph_manager_suggestions(user_id BIGINT PRIMARY KEY REFERENCES users(id),graph_manager_external_id TEXT,graph_manager_name TEXT,graph_manager_email TEXT,suggested_at TIMESTAMPTZ,local_manager_user_id BIGINT REFERENCES users(id),override_reason TEXT,overridden_by BIGINT REFERENCES users(id),overridden_at TIMESTAMPTZ,source VARCHAR(50) NOT NULL DEFAULT 'microsoft_graph_read_only',updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS finance_position_duty_templates(id BIGSERIAL PRIMARY KEY,position_pattern TEXT NOT NULL,finance_function_id BIGINT REFERENCES finance_functions(id),duty_name TEXT NOT NULL,duty_description TEXT,default_weight NUMERIC(6,2) NOT NULL CHECK(default_weight BETWEEN 0 AND 100),active BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(position_pattern,duty_name));
CREATE TABLE IF NOT EXISTS finance_employee_duties(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),finance_function_id BIGINT REFERENCES finance_functions(id),template_id BIGINT REFERENCES finance_position_duty_templates(id),duty_name TEXT NOT NULL,duty_description TEXT,weight NUMERIC(6,2) NOT NULL CHECK(weight BETWEEN 0 AND 100),progress_percent NUMERIC(6,2) NOT NULL DEFAULT 0 CHECK(progress_percent BETWEEN 0 AND 100),status VARCHAR(30) NOT NULL DEFAULT 'not_started',target_date DATE,created_by BIGINT REFERENCES users(id),updated_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS finance_kpis(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,description TEXT,owner_user_id BIGINT REFERENCES users(id),finance_function_id BIGINT REFERENCES finance_functions(id),period_start DATE NOT NULL,period_end DATE NOT NULL,target_value NUMERIC(18,4),actual_value NUMERIC(18,4),unit VARCHAR(40),weight NUMERIC(6,2) NOT NULL DEFAULT 0 CHECK(weight BETWEEN 0 AND 100),progress_percent NUMERIC(6,2) NOT NULL DEFAULT 0 CHECK(progress_percent BETWEEN 0 AND 100),status VARCHAR(30) NOT NULL DEFAULT 'active',created_by BIGINT REFERENCES users(id),updated_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(period_end>=period_start));
CREATE TABLE IF NOT EXISTS finance_boardroom_bookings(id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,organiser_user_id BIGINT NOT NULL REFERENCES users(id),purpose TEXT,external_auditors_present BOOLEAN NOT NULL DEFAULT FALSE,external_auditor_details TEXT,temporary_work_location BOOLEAN NOT NULL DEFAULT FALSE,status VARCHAR(20) NOT NULL DEFAULT 'booked',created_by BIGINT REFERENCES users(id),updated_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(ends_at>starts_at),CHECK(NOT temporary_work_location OR external_auditors_present));
CREATE INDEX IF NOT EXISTS ix_finance_duties_user ON finance_employee_duties(user_id,status);
CREATE INDEX IF NOT EXISTS ix_finance_kpis_owner_period ON finance_kpis(owner_user_id,period_start,period_end);
CREATE INDEX IF NOT EXISTS ix_finance_boardroom_time ON finance_boardroom_bookings(starts_at,ends_at) WHERE status='booked';
INSERT INTO finance_position_duty_templates(position_pattern,duty_name,duty_description,default_weight) VALUES
('%finance manager%','Finance governance and team oversight','Govern Finance operations, delegation, controls, deadlines and performance.',35),
('%finance manager%','Management reporting','Maintain CFO-ready reporting, risks, KPIs and corrective actions.',25),
('%accountant manager%','Financial review and control','Review reconciliations, reporting quality, compliance and team output.',35),
('%accountant%','Reconciliations and financial records','Maintain accurate reconciliations, journals, schedules and supporting records.',35),
('%accountant assistant%','Finance transaction support','Capture, validate and follow up Finance transactions and supporting documents.',40),
('%office manager%','Finance administration coordination','Coordinate Finance administration, correspondence, records and deadlines.',40)
ON CONFLICT(position_pattern,duty_name) DO UPDATE SET duty_description=EXCLUDED.duty_description,default_weight=EXCLUDED.default_weight,active=TRUE,updated_at=NOW();
COMMIT;
